    """
    This is a generic jit handle that counts the number of activations for any
    operation given the output shape.
    """
    out_shape = get_shape(outputs[0])
    ac_count = prod(out_shape)
    if op_name is None:
        return ac_count
    else:
        return Counter({op_name: ac_count})
